        // verbatim from Trip.java
        boolean overlapsTrip(Trip trip){
            return trip.getStartDate().before(end) && trip.getEndDate().after(start);
        }
    }

    // OLD behaviour
    static boolean oldTripExists(List<Trip> db, Trip t){
        for (Trip o : db) if (t.overlapsTrip(o)) return true;
        return false;
    }
    // NEW behaviour (patched)
    static boolean newTripExists(List<Trip> db, Trip t, UUID excludeId){
        for (Trip o : db){
            if (excludeId != null && excludeId.equals(o.getId())) continue;
            if (t.overlapsTrip(o)) return true;
        }
        return false;
    }

    public static void main(String[] a){
        long DAY = 86400000L;
        UUID id1 = UUID.randomUUID(), id2 = UUID.randomUUID();

        // Saved trip: Jan1 -> Jan10
        Trip saved = new Trip("saved", id1, 1*DAY, 10*DAY);
        List<Trip> db = new ArrayList<>(); db.add(saved);

        // User edits that same trip, moving start to Jan5 (edit copy keeps the id)
        Trip edited = new Trip("edited", id1, 5*DAY, 10*DAY);

        System.out.println("== Repro: edit a trip's date ==");
        System.out.println("  OLD tripExists -> " + oldTripExists(db, edited) + "   (true = save blocked = BUG)");
        System.out.println("  NEW tripExists -> " + newTripExists(db, edited, id1) + "   (false = save allowed = FIXED)");

        // Regression 1: a genuinely overlapping *different* trip must still be rejected
        Trip other = new Trip("other", id2, 3*DAY, 7*DAY);
        System.out.println("== Regression: different trip that really overlaps ==");
        System.out.println("  NEW tripExists -> " + newTripExists(db, other, id2) + "   (expect true)");

        // Regression 2: a different, non-overlapping trip must still be accepted
        Trip far = new Trip("far", id2, 20*DAY, 25*DAY);
        System.out.println("== Regression: different trip, no overlap ==");
        System.out.println("  NEW tripExists -> " + newTripExists(db, far, id2) + "   (expect false)");

        // Regression 3: existing LogbookTest semantics - tripExists(trip) with no exclusion
        System.out.println("== Regression: LogbookTest:472 assertTrue(tripExists(trip1)) ==");
        System.out.println("  NEW tripExists(saved, null) -> " + newTripExists(db, saved, null) + "   (expect true)");

        // Regression 4: editing a trip into a slot occupied by another trip is still rejected
        db.add(new Trip("second", id2, 20*DAY, 25*DAY));
        Trip clash = new Trip("edited-clash", id1, 19*DAY, 22*DAY);
        System.out.println("== Regression: edit that collides with a DIFFERENT trip ==");
        System.out.println("  NEW tripExists -> " + newTripExists(db, clash, id1) + "   (expect true)");
    }
}
