76	            CatchTable.Columns.CATCH_RESULT + " INTEGER, " +
77	            CatchTable.Columns.IS_FAVORITE + " INTEGER, " +
78	            CatchTable.Columns.SELECTED + " INTEGER, " +
79	            CatchTable.Columns.LENGTH + " REAL, " +
