182	    public static ArrayList<UserDefineObject> queryUsedUserDefineObject(String table, String resultColumn, String superColumn, UUID superId, UsedQueryCallbacks callbacks) {
183	        ArrayList<UserDefineObject> objs = new ArrayList<>();
184	        Cursor cursor = simpleQuery(table, resultColumn, superColumn + " = ?", new String[]{superId.toString()});
185	
186	        if (cursor.moveToFirst())
187	            while (!cursor.isAfterLast()) {
188	                UUID id = UUID.fromString(cursor.getString(cursor.getColumnIndex(resultColumn)));
189	                objs.add(callbacks.getFromLogbook(id));
190	                cursor.moveToNext();
191	            }
192	
193	        cursor.close();
194	        return objs;
